    </a>
  </header>

  <div class="heroes__filters">
    <div class="heroes__search">
      <label hlmLabel for="roster-search" class="heroes__label">Search heroes</label>
      <ng-icon name="lucideSearch" aria-hidden="true" class="heroes__search-icon" />
      <input
        hlmInput
        id="roster-search"
        type="search"
        class="heroes__search-input"
        placeholder="Search by name, alias or ID"
        #search
        (input)="vm.setSearch(search.value)"
      />
    </div>

    <hlm-select class="heroes__class-filter" [value]="vm.classFilter()" (valueChange)="vm.setClassFilter($event)">
      <hlm-select-trigger class="heroes__class-trigger" aria-label="Filter by power class">
        <hlm-select-value />
      </hlm-select-trigger>
      <hlm-select-content *hlmSelectPortal>
        <hlm-select-group>
          <hlm-select-label>Power class</hlm-select-label>
          @for (option of vm.classOptions; track option) {
            <hlm-select-item [value]="option">{{ option }}</hlm-select-item>
          }
        </hlm-select-group>
      </hlm-select-content>
    </hlm-select>
  </div>

  <div hlmTableContainer class="heroes__table-wrap">
    <table hlmTable class="heroes__table">
      <caption hlmCaption class="heroes__caption">Heroes on the roster, strongest first</caption>
      <thead hlmTHead>
        <tr hlmTr>
          <th hlmTh scope="col">Hero</th>
          <th hlmTh scope="col">Class</th>
          <th hlmTh scope="col">Power</th>
          <th hlmTh scope="col">Status</th>
          <th hlmTh scope="col">Clearance</th>
          <th hlmTh scope="col">Actions</th>
        </tr>
      </thead>
      <tbody hlmTBody>
        @for (row of vm.rows(); track row.hero.id) {
          <tr hlmTr>
            <td hlmTd>
              <div class="heroes__identity">
                <hlm-avatar size="sm" aria-hidden="true">
                  <span hlmAvatarFallback>{{ row.initials }}</span>
                </hlm-avatar>
                <div class="heroes__names">
                  <span class="heroes__name">{{ row.hero.name }}</span>
                  <span class="heroes__id">{{ row.hero.id }}</span>
                </div>
              </div>
            </td>
            <td hlmTd>
              <span hlmBadge variant="secondary">{{ row.hero.powerClass }}</span>
            </td>
            <td hlmTd>{{ row.hero.powerIndex }}</td>
            <td hlmTd>
              <span hlmBadge variant="outline">
                <span
                  class="heroes__dot"
                  aria-hidden="true"
                  [class.heroes__dot--active]="row.hero.status === 'Active'"
                  [class.heroes__dot--injured]="row.hero.status === 'Injured'"
                  [class.heroes__dot--reserve]="row.hero.status === 'Reserve'"
                  [class.heroes__dot--mia]="row.hero.status === 'MIA'"
                ></span>
                {{ row.hero.status }}
              </span>
            </td>
            <td hlmTd>Tier {{ row.hero.clearance }}</td>
            <td hlmTd>
              <a
                hlmBtn
                variant="ghost"
                size="icon"
                [routerLink]="['/detail', row.hero.id]"
                [attr.aria-label]="'Edit ' + row.hero.name"
              >
                <ng-icon name="lucidePencil" aria-hidden="true" />
              </a>
            </td>
          </tr>
        } @empty {
          <tr hlmTr>
            <td hlmTd colspan="6">No heroes match these filters.</td>
          </tr>
        }
      </tbody>
    </table>
  </div>

  <footer class="heroes__footer">
    <p class="heroes__count" aria-live="polite">
      {{ vm.visibleCount() }} of {{ vm.totalCount() }} heroes
    </p>
    <p class="heroes__sort">Sorted by power</p>
  </footer>
</section>

