import { Component, input } from '@angular/core';
import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucideActivity, lucideTriangleAlert, lucideUserCheck, lucideZap } from '@ng-icons/lucide';
import { HlmCardImports } from '@spartan-ng/helm/card';

/** The icons a stat tile can show. Each one is registered on this component below. */
export type StatIcon = 'lucideUserCheck' | 'lucideActivity' | 'lucideZap' | 'lucideTriangleAlert';

@Component({
  selector: 'app-stat-tile',
  imports: [NgIcon, ...HlmCardImports],
  providers: [
    provideIcons({ lucideUserCheck, lucideActivity, lucideZap, lucideTriangleAlert }),
  ],
  templateUrl: './stat-tile.html',
  styleUrl: './stat-tile.css',
})
export class StatTile {
  readonly label = input.required<string>();
  readonly value = input.required<number>();
  readonly icon = input.required<StatIcon>();
}
<article hlmCard class="stat-tile">
  <div hlmCardHeader class="stat-tile__header">
    <p class="stat-tile__label">{{ label() }}</p>
    <ng-icon class="stat-tile__icon" [name]="icon()" aria-hidden="true" />
  </div>
  <div hlmCardContent>
    <p class="stat-tile__value">{{ value() }}</p>
  </div>
</article>
====
<div class="dashboard">
<header class="dashboard__header">
  <div class="dashboard__intro">
    <h1 class="dashboard__title">Operations Dashboard</h1>
    <p class="dashboard__subtitle">Example data. Nothing here reflects a real roster.</p>
  </div>
  <a hlmBtn routerLink="/recruit">
    <ng-icon name="lucideUserPlus" aria-hidden="true" />
    Recruit
  </a>
</header>

<section class="dashboard__stats" aria-label="Key figures">
  @for (stat of vm.stats(); track stat.label) {
    <app-stat-tile [label]="stat.label" [value]="stat.value" [icon]="stat.icon" />
  }
</section>

<section class="dashboard__section" aria-labelledby="top-heroes-heading">
  <div class="dashboard__section-head">
    <h2 id="top-heroes-heading" class="dashboard__section-title">Top heroes this cycle</h2>
    <a hlmBtn variant="outline" size="sm" routerLink="/roster">View all roster</a>
  </div>
  <div class="dashboard__hero-grid">
    @for (hero of vm.topHeroes(); track hero.id) {
      <app-hero-card [hero]="hero" />
    }
  </div>
</section>

<section class="dashboard__section" aria-labelledby="roster-heading">
  <div class="dashboard__section-head">
    <h2 id="roster-heading" class="dashboard__section-title">Roster</h2>
    <span hlmBadge variant="secondary">{{ vm.rosterCount() }} heroes</span>
  </div>
</section>
</div>
