  @apply w-full;
}

.heroes__table-wrap {
  @apply min-w-0;
}

.heroes__table {
  @apply min-w-[40rem];
}

.heroes__caption {
  @apply sr-only;
}

.heroes__identity {
  @apply flex min-w-0 items-center gap-3;
}

.heroes__names {
  @apply flex min-w-0 flex-col;
}

.heroes__name {
  @apply truncate font-medium text-foreground;
