input.content:
@reference "../../styles.css";

.hero-detail {
  @apply grid min-w-0 grid-cols-1 gap-6;
}

.hero-detail__back {
  @apply justify-self-start;
}

.hero-detail__header {
  @apply flex flex-wrap items-start justify-between gap-4;
}

.hero-detail__identity {
  @apply flex min-w-0 items-center gap-4;
}

.hero-detail__names {
  @apply flex min-w-0 flex-col gap-1;
}

.hero-detail__id {
  @apply text-xs text-muted-foreground;
}

.hero-detail__title {
  @apply text-2xl font-semibold tracking-tight text-foreground;
}

.hero-detail__alias {
  @apply text-sm text-muted-foreground;
}

.hero-detail__badges {
  @apply flex flex-wrap items-center gap-2;
}

.hero-detail__dot {
  @apply inline-block size-2 shrink-0 rounded-full bg-muted-foreground;
}

.hero-detail__dot--active {
  @apply bg-success;
}

.hero-detail__dot--injured {
  @apply bg-warning;
}

.hero-detail__dot--reserve {
  @apply bg-info;
}

.hero-detail__dot--mia {
  @apply bg-destructive;
}

.hero-detail__actions {
  @apply flex flex-wrap items-center gap-2;
}

.hero-detail__retire {
  @apply contents;
}

.hero-detail__notice {
  @apply min-h-5 text-sm text-muted-foreground;
}

.hero-detail__tabs {
  @apply grid min-w-0 gap-4;
}

.hero-detail__tab-scroll {
  @apply max-w-full overflow-x-auto;
}

.hero-detail__tab-list {
  @apply w-max;
}

.hero-detail__panel {
  @apply grid min-w-0 gap-4;
}

.hero-detail__overview {
  @apply grid min-w-0 grid-cols-1 gap-4 lg:grid-cols-2;
}

.hero-detail__summary {
  @apply grid min-w-0 content-start gap-3;
}

.hero-detail__section-title {
  @apply text-base font-semibold text-foreground;
}

.hero-detail__stats {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-3;
}

.hero-detail__dossier {
  @apply min-w-0;
}

.hero-detail__facts {
  @apply grid gap-3 text-sm;
}

.hero-detail__fact {
  @apply flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1;
}

.hero-detail__term {
  @apply text-muted-foreground;
}

.hero-detail__value {
  @apply min-w-0 break-words text-right font-medium text-foreground;
}

.hero-detail__notes-title {
  @apply mt-4 text-sm font-semibold text-foreground;
}

.hero-detail__notes {
  @apply text-sm text-muted-foreground;
}

.hero-detail__two-up {
  @apply grid min-w-0 grid-cols-1 gap-4 lg:grid-cols-2;
}

.hero-detail__card {
  @apply min-w-0;
}

.hero-detail__meters {
  @apply grid gap-4;
}

.hero-detail__note {
  @apply mt-3 text-sm text-muted-foreground;
}

.hero-detail__form {
  @apply grid min-w-0 gap-6;
}

.hero-detail__fields {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-2;
}

.hero-detail__field {
  @apply min-w-0;
}

.hero-detail__field--wide {
  @apply sm:col-span-2;
}

.hero-detail__select {
  @apply w-full;
}

.hero-detail__form-actions {
  @apply flex flex-wrap justify-end gap-2;
}

.hero-detail__missing {
  @apply grid gap-2;
}

