input.command:
cd "$TEMP/verify-detail" && cat > verify.mjs <<'EOF'
import { chromium } from 'file:///D:/Repos/angular-jig/node_modules/playwright/index.mjs';
import http from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join } from 'node:path';

const ROOT = 'D:/Repos/angular-jig/dist/angular-jig/browser';
const TYPES = { '.js': 'text/javascript', '.css': 'text/css', '.html': 'text/html', '.json': 'application/json', '.svg': 'image/svg+xml', '.ico': 'image/x-icon', '.woff2': 'font/woff2' };
const server = http.createServer(async (req, res) => {
  const path = decodeURIComponent(new URL(req.url, 'http://x').pathname);
  let file = join(ROOT, path);
  try { if ((await stat(file)).isDirectory()) file = join(file, 'index.html'); } catch { file = join(ROOT, 'index.html'); }
  try {
    const body = await readFile(file);
    res.writeHead(200, { 'content-type': TYPES[extname(file)] ?? 'application/octet-stream' });
    res.end(body);
  } catch { res.writeHead(404); res.end(); }
});
await new Promise((r) => server.listen(4311, r));
const base = 'http://localhost:4311';
const browser = await chromium.launch();
const results = [];
const check = (name, ok, extra = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${extra}`);

for (const width of [375, 1280]) {
  const page = await browser.newPage({ viewport: { width, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto(base + '/detail/HRO-0007');
  await page.waitForSelector('h1:has-text("Silverwing")', { timeout: 15000 });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  check(`[${width}] no page horizontal overflow`, overflow <= 1, `overflow=${overflow}`);

  // Powers + Missions tabs render
  await page.getByRole('button', { name: 'Powers', exact: true }).click();
  check(`[${width}] powers tab shows meter`, (await page.locator('[role=meter]').count()) >= 2);
  await page.getByRole('button', { name: 'Edit', exact: true }).click();
  await page.waitForSelector('#hero-name');
  check(`[${width}] edit form prefilled`, (await page.inputValue('#hero-name')) === 'Silverwing');

  // Validation: empty name blocks save
  await page.fill('#hero-name', '');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await page.waitForTimeout(300);
  const nameErr = await page.locator('hlm-field-error').first().textContent().catch(() => '');
  check(`[${width}] empty name shows schema error`, /required/i.test(nameErr || ''), `err="${(nameErr || '').trim()}"`);
  check(`[${width}] invalid save leaves notice empty`, !(await page.textContent('.hero-detail__notice')).includes('saved'));

  // Valid save
  await page.fill('#hero-name', 'Silverwing II');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await page.waitForTimeout(300);
  check(`[${width}] valid save shows notice`, (await page.textContent('.hero-detail__notice')).includes('Changes saved'));
  check(`[${width}] header reflects saved name`, (await page.textContent('h1.hero-detail__title')).includes('Silverwing II'));

  // Retire dialog opens and cancels without navigating
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  await page.waitForSelector('[role=dialog]', { timeout: 5000 });
  check(`[${width}] retire dialog opens`, true);
  await page.getByRole('button', { name: 'Cancel', exact: true }).click();
  await page.waitForTimeout(300);
  check(`[${width}] cancel keeps hero`, page.url().includes('/detail/HRO-0007'));

  // Deploy an Active hero, notice updates
  await page.getByRole('button', { name: 'Deploy', exact: true }).click();
  await page.waitForTimeout(200);
  check(`[${width}] deploy notice`, (await page.textContent('.hero-detail__notice')).includes('deployed'));

  // Retire for real, navigates to roster
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  await page.waitForSelector('[role=dialog]');
  await page.getByRole('button', { name: 'Retire hero', exact: true }).click();
  await page.waitForURL('**/roster', { timeout: 5000 }).catch(() => {});
  check(`[${width}] retire navigates to roster`, page.url().endsWith('/roster'), page.url());

  // Unknown id
  await page.goto(base + '/detail/HRO-9999');
  await page.waitForSelector('h1:has-text("Hero not found")', { timeout: 15000 }).catch(() => {});
  check(`[${width}] unknown id shows not-found`, (await page.locator('h1').first().textContent()).includes('not found'));

  check(`[${width}] no page errors`, errors.length === 0, errors.slice(0, 5).join(' | '));
  await page.close();
}
await browser.close();
server.close();
console.log(results.join('\n'));
EOF
timeout 300000 node verify.mjs 2>&1 | tail -60

